const a=["全部","宏观经济","市场动态","公司新闻","行业研究","政策解读","AI解读"],t=[{id:1,title:"央行宣布降准0.5个百分点 释放长期资金约1.2万亿",category:"宏观经济",source:"财联社",author:"AI资讯",publishTime:"2小时前",views:15800,likes:423,aiSummary:"降准利好银行、地产板块，但短期市场可能已部分定价，AI 建议关注银行龙头和地产龙头的后续表现。",impact:{direction:"positive",level:"high",affectedStocks:["600036.SH","601318.SH","000001.SZ"],analysis:"降准将直接降低银行负债成本约 0.3-0.5 个百分点，同时向市场释放流动性信号，对权益资产整体利好。"},isFeatured:!0,tags:["重磅","政策"],content:["中国人民银行决定于2025年6月15日下调金融机构存款准备金率0.5个百分点（不含已执行5%存款准备金率的金融机构）。此次降准预计释放长期资金约1.2万亿元，旨在保持流动性合理充裕，支持实体经济发展。","市场分析认为，此次降准超出市场预期，显示政策面稳增长决心。对资本市场而言，降准有助于提振投资者信心，特别是对银行、地产等资金敏感型板块形成直接利好。",'AI 模型分析：从历史经验看，降准后 1-3 个月内，上证指数平均上涨 2-3%。但本次降准市场已有一定预期，短期市场可能呈现"利好兑现"走势，建议关注金融板块的逢低布局机会。']},{id:2,title:"5月CPI同比上涨0.8% PPI同比降幅收窄",category:"宏观经济",source:"国家统计局",author:"数据发布",publishTime:"4小时前",views:8200,likes:156,aiSummary:"通胀温和有利于货币政策维持宽松基调，PPI 降幅收窄显示工业需求回暖。",impact:{direction:"neutral",level:"medium",affectedStocks:["000858.SZ","600519.SH"],analysis:"通胀数据温和，短期内不会对货币政策形成制约。PPI 改善有利于中游制造业盈利修复。"},isFeatured:!1,tags:["宏观数据"],content:["国家统计局数据显示，2025年5月份全国居民消费价格（CPI）同比上涨0.8%，环比下降0.1%。工业生产者出厂价格（PPI）同比下降2.5%，降幅比上月收窄0.4个百分点。","专家表示，当前通胀压力较小，为货币政策继续保持宽松提供了空间。PPI 降幅持续收窄，反映出工业领域需求正在逐步恢复。"]},{id:3,title:"宁德时代发布第三代CTP电池 能量密度提升30%",category:"公司新闻",source:"公司公告",author:"新能源观察",publishTime:"5小时前",views:25600,likes:892,aiSummary:"宁德时代技术领先优势进一步扩大，利好产业链上下游，AI 维持强烈看多评级。",impact:{direction:"positive",level:"high",affectedStocks:["300750.SZ","002594.SZ","300124.SZ"],analysis:"新电池技术将巩固宁德时代的全球龙头地位，同时也利好下游新能源车企，推动行业整体技术升级。"},isFeatured:!0,tags:["技术突破","利好"],content:["宁德时代今日正式发布第三代 CTP（Cell to Pack）电池技术，该技术可使得电池包体积利用率提升 25%，能量密度提升 30%，成本下降 15%。","新款电池将率先搭载于多家头部新能源车企的新车型中，预计 2025 年下半年开始量产交付。分析人士认为，这将进一步巩固宁德时代在全球动力电池市场的领先地位。",'AI 模型分析认为，该技术突破超预期，将强化宁德时代的估值逻辑。维持此前给出的"强烈看多"评级和 228 元目标价。']},{id:4,title:"半导体行业景气度回升 存储芯片价格连续三个月上涨",category:"行业研究",source:"行业研究",author:"芯研究",publishTime:"6小时前",views:9800,likes:345,aiSummary:'半导体周期拐点信号明确，AI 模型上调行业评级至"增持"，重点关注存储和设备龙头。',impact:{direction:"positive",level:"high",affectedStocks:["688981.SH","688012.SH","002371.SZ"],analysis:"存储芯片价格持续回升是行业周期见底的重要信号，半导体设备和材料将率先受益。"},isFeatured:!0,tags:["周期反转"],content:["根据多家研究机构数据，DRAM 和 NAND Flash 存储芯片价格已连续三个月环比上涨，涨幅分别为 8% 和 12%。市场普遍认为半导体周期底部已确认，新一轮上升周期正在开启。","AI 模型分析：从历史规律看，半导体周期通常持续 2-3 年。当前处于周期早期阶段，具有较大投资机会。建议重点关注存储芯片、半导体设备和材料三个细分领域。"]},{id:5,title:"证监会发布深化资本市场改革新措施",category:"政策解读",source:"证监会",author:"政策研究员",publishTime:"8小时前",views:12500,likes:567,aiSummary:"改革措施中长期利好资本市场健康发展，短期对券商板块形成催化。",impact:{direction:"positive",level:"medium",affectedStocks:["600030.SH","300059.SZ"],analysis:"资本市场改革持续深化有利于提升市场活力和投资者信心，券商作为直接受益方值得关注。"},isFeatured:!1,tags:["政策利好"],content:["中国证监会今日发布《关于进一步深化资本市场改革的若干措施》，涉及优化发行上市制度、完善交易机制、加强投资者保护等多个方面。"]},{id:6,title:"AI算力需求爆发 2025年AI芯片市场规模预计增长60%",category:"行业研究",source:"Gartner",author:"科技前瞻",publishTime:"10小时前",views:18800,likes:723,aiSummary:"AI 算力需求确定性高，AI 芯片国产替代空间巨大，关注相关标的投资机会。",impact:{direction:"positive",level:"high",affectedStocks:["002230.SZ","688981.SH","002415.SZ"],analysis:"全球 AI 算力投资持续高增，国产 AI 芯片替代加速，产业链上下游均有望受益。"},isFeatured:!1,tags:["AI","高增长"],content:["据 Gartner 最新预测，2025 年全球 AI 芯片市场规模将达到 980 亿美元，同比增长 60%。其中，用于大模型训练的 GPU 和 ASIC 芯片需求最为旺盛。"]},{id:7,title:"国际油价连续下跌 欧佩克+考虑增产计划",category:"市场动态",source:"路透社",author:"能源前线",publishTime:"12小时前",views:7200,likes:234,aiSummary:"油价下跌利好航空、化工等下游行业，但对新能源板块情绪可能产生短期扰动。",impact:{direction:"negative",level:"low",affectedStocks:["002594.SZ","300750.SZ"],analysis:"油价下跌可能短期影响新能源替代节奏，不改长期趋势。下游航空、化工等行业成本端受益。"},isFeatured:!1,tags:["油价"],content:["国际油价连续第三周下跌，WTI 原油跌破 75 美元/桶。消息人士称欧佩克+正在讨论 2025 年下半年的增产计划。"]},{id:8,title:"五一消费数据出炉 文旅消费同比增长18%",category:"宏观经济",source:"商务部",author:"消费前线",publishTime:"1天前",views:6500,likes:189,aiSummary:"消费复苏势头强劲，利好消费板块，特别是旅游、餐饮、白酒等细分领域。",impact:{direction:"positive",level:"medium",affectedStocks:["000858.SZ","600519.SH","002714.SZ"],analysis:"消费数据超预期，验证消费复苏逻辑。白酒板块有望迎来估值修复行情。"},isFeatured:!1,tags:["消费复苏"],content:["商务部数据显示，2025年五一假期全国文旅消费总额同比增长 18%，较 2019 年同期增长 12%。消费复苏势头强劲。"]},{id:9,title:"国产大模型通过备案数量突破100个 商业化提速",category:"AI解读",source:"AI观察",author:"智投AI",publishTime:"1天前",views:15600,likes:678,aiSummary:'AI 产业进入加速落地期，算力、应用、模型三条主线均有机会，AI 维持"超配"建议。',impact:{direction:"positive",level:"medium",affectedStocks:["002230.SZ","002415.SZ","300059.SZ"],analysis:"AI 大模型备案加速，行业规范化利好龙头企业。AI 应用商业化有望提速，关注有场景优势的标的。"},isFeatured:!0,tags:["AI产业","趋势"],content:['截至 2025 年 5 月，通过国家网信办备案的国产大模型数量已突破 100 个，较 2024 年底增长超过一倍。大模型应用正在从"可用"向"好用"迈进。',"AI 模型解读：大模型备案数量激增意味着 AI 产业正从研发阶段进入大规模商业化阶段。算力基础设施、AI 应用、模型服务三条投资主线均值得重点关注。"]},{id:10,title:"北向资金本月净流入超800亿元 创年内新高",category:"市场动态",source:"Wind",author:"资金观察",publishTime:"1天前",views:11200,likes:456,aiSummary:"外资持续流入表明对中国市场的信心增强，A 股优质资产吸引力提升。",impact:{direction:"positive",level:"medium",affectedStocks:["600519.SH","300750.SZ","601318.SH"],analysis:"北向资金持续净买入是 A 股市场的重要支撑力量，外资偏好的大消费和新能源龙头值得关注。"},isFeatured:!1,tags:["外资动向"],content:["截至今日收盘，5 月份北向资金累计净流入 A 股 826 亿元，已超过 4 月份全月水平，创年内单月净流入新高。"]},{id:11,title:"新能源汽车渗透率突破55% 行业进入存量竞争阶段",category:"行业研究",source:"乘联会",author:"汽车研究",publishTime:"2天前",views:9800,likes:389,aiSummary:'新能源车渗透率突破 55% 后增速可能放缓，行业从"增量"转向"存量"，龙头优势将进一步凸显。',impact:{direction:"neutral",level:"medium",affectedStocks:["300750.SZ","002594.SZ","300124.SZ"],analysis:"渗透率提升斜率放缓，但龙头公司凭借技术优势和规模效应仍有望维持增长。"},isFeatured:!1,tags:["新能源"],content:["乘联会最新数据显示，2025 年 1-4 月新能源汽车渗透率已达 55.8%，较 2024 年全年提升 8 个百分点。"]},{id:12,title:"多家券商发布下半年投资策略 看好科技成长主线",category:"市场动态",source:"券商策略",author:"策略汇总",publishTime:"2天前",views:7800,likes:234,aiSummary:"券商一致看好科技成长方向，AI 和半导体是共识度最高的两条主线。",impact:{direction:"positive",level:"low",affectedStocks:["002230.SZ","688981.SH","688012.SH"],analysis:"机构共识形成可能推动相关板块获得超额收益，但需注意一致预期过于拥挤的风险。"},isFeatured:!1,tags:["策略"],content:["随着 2025 年过半，多家头部券商陆续发布下半年投资策略报告。科技成长方向成为共识度最高的配置主线。"]}];function s(e){return t.find(i=>i.id===e)||null}export{t as N,a,s as g};
